import java.io.BufferedReader;
import java.io.InputStreamReader;

import org.apache.commons.io.FileUtils;

import org.json.JSONArray;
import org.json.JSONObject;

public class Issue {

	public Issue(JSONObject jsonObject) {
		_key = jsonObject.get("key");

		JSONObject fieldsJSONObject = jsonObject.get("fields");

		_summary = fieldsJSONObject.get("summary");

		Object object = fieldsJSONObject.get("description");

		if (!object.equals(JSONObject.NULL)) {
			_description = fieldsJSONObject.get("description");
		}
		else {
			_description = "";
		}

		_initBusinessValues();

		_id = _businessValue + _summary;
	}

	private void _blah(String number) {
		String businessValueNumber = project.getProperty("business.value." + number);

		if (businessValueNumber != null) {
			List businessValues = new ArrayList();

			String descriptionLowerCase = _description.toLowerCase();

			for (String businessValue : businessValueNumber.split(",")) {
				businessValue = businessValue.trim();

				String businessValueLowerCase = businessValue.toLowerCase();

				if (descriptionLowerCase.matches("[\\S\\s]*\\* " + businessValueLowerCase + "[\\S\\s]*")) {
					businessValues.add(businessValue);

					_businessValues.add(businessValue);

					_businessValue += Integer.parseInt(number);

					_map.put(number, businessValues);
				}
			}
		}
	}

	private void _initBusinessValues() {
		_businessValueNumbers = project.getProperty("business.values").split(",");

		for (String number : _businessValueNumbers) {
			_blah(number);
		}
	}

	public String getID() {
		return _id;
	}

	public String getKey() {
		return _key;
	}

	public String getSummary() {
		return _summary;
	}

	public String getDescription() {
		return _description;
	}

	public int getBusinessValue() {
		return _businessValue;
	}

	public List getBusinessValues() {
		return _businessValues;
	}

	public String getBusinessValueBreakdown() {
		StringBuilder sb = new StringBuilder();

		for (String number : _businessValueNumbers) {
			if (_map.containsKey(number)) {
				sb.append(number + " " + _map.get(number));
				sb.append("\n");
			}
		}

		return sb.toString();
	}

	private String _id;
	private String _key;
	private String _summary;
	private String _description;
	private int _businessValue;
	private List _businessValues = new ArrayList();
	private String[] _businessValueNumbers;
	private Map _map = new HashMap();

}

public String getJQL() {
	return project.getProperty("jql.query").replaceAll(" ", "%20");
}

public JSONObject getJSONObject(String curlOptions) throws Exception {
	Runtime runtime = Runtime.getRuntime();

	Process process = runtime.exec("curl " + curlOptions);

	InputStreamReader inputStreamReader = new InputStreamReader(
		process.getInputStream());

	BufferedReader inputBufferedReader = new BufferedReader(
		inputStreamReader);

	String line = null;

	StringBuilder sb = new StringBuilder();

	while ((line = inputBufferedReader.readLine()) != null) {
		sb.append(line);
	}

	return new JSONObject(sb.toString());
}

JSONObject jsonObject = getJSONObject(" -u michael.hashimoto:Cr38Cl3an https://issues.liferay.com/rest/api/latest/search?jql=" + getJQL() + "&maxResults=200");

JSONArray jsonArray = jsonObject.getJSONArray("issues");

StringBuilder sb = new StringBuilder();

Map mapper = new TreeMap();

for (int i = 0; i < jsonArray.length(); i++) {
	Object object = jsonArray.get(i);

	if (object.equals(JSONObject.NULL)) {
		continue;
	}

	JSONObject issueJSONObject = jsonArray.get(i);

	JSONObject jiraJSONObject = getJSONObject(" -u michael.hashimoto:Cr38Cl3an https://issues.liferay.com/rest/api/latest/issue/" + issueJSONObject.get("key"));

	System.out.println("Reading https://issues.liferay.com/browse/" + issueJSONObject.get("key"));

	Issue issue = new Issue(jiraJSONObject);

	mapper.put(issue.getID(), issue);
}

Set set = mapper.keySet();

System.out.println("\nOrder by Business Value:\n");

for (String key : set) {
	Issue issue = mapper.get(key);

	System.out.println(issue.getBusinessValue() + " - " + issue.getKey() + " - " + issue.getBusinessValues());
}

File file = new File("hello.txt");

FileUtils.write(file, sb.toString());
